contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (withdrawAmount)); require(withdrawAmount <= 1000000000000000000000000000000);
        require(withdrawAmount > 0);

        c.deposit{value: withdrawAmount}(); if (__ESBMC_reverted()) return;

        uint256 contractBefore = address(c).balance;

        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 contractAfter = address(c).balance;

        assert(
            withdrawAmount == 0 ||
            (!reverted && contractBefore - contractAfter == withdrawAmount) ||
            (reverted && contractBefore < withdrawAmount)
        );
    }

    receive() external payable {}
}

