// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 withdrawAmount) internal {
        withdrawAmount = bound(withdrawAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(withdrawAmount > 0);
        try c.deposit{value: withdrawAmount}() {} catch { return; }
        uint256 contractBefore = address(c).balance;
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 contractAfter = address(c).balance;
        assertTrue(withdrawAmount == 0 ||
            (!reverted && contractBefore - contractAfter == withdrawAmount) ||
            (reverted && contractBefore < withdrawAmount));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
